package cn.longer233.gamenarrator.mobile;

public final class AudioPeakAnalyzer {
    private AudioPeakAnalyzer(){ }
    public static final class Result {private final float peak,suggestedGain;private final int overloadBuckets,silentBuckets,longestOverload,longestSilence,total;Result(float peak,float suggestedGain,int overloadBuckets,int silentBuckets,int longestOverload,int longestSilence,int total){this.peak=peak;this.suggestedGain=suggestedGain;this.overloadBuckets=overloadBuckets;this.silentBuckets=silentBuckets;this.longestOverload=longestOverload;this.longestSilence=longestSilence;this.total=total;}public float peak(){return peak;}public float suggestedGain(){return suggestedGain;}public int overloadBuckets(){return overloadBuckets;}public int silentBuckets(){return silentBuckets;}public int longestOverload(){return longestOverload;}public int longestSilence(){return longestSilence;}public int total(){return total;}public boolean overloaded(){return longestOverload>=2||overloadBuckets>=Math.max(3,total/100);}public boolean mostlySilent(){return silentBuckets>=total*.8f;}}
    public static Result analyze(float[] points){if(points==null||points.length==0)return new Result(0,1,0,0,0,0,0);float peak=0;int overload=0,silent=0,overloadRun=0,silentRun=0,maxOverload=0,maxSilence=0;for(float raw:points){float value=Math.max(0,Math.min(1,raw));peak=Math.max(peak,value);if(value>=.985f){overload++;overloadRun++;maxOverload=Math.max(maxOverload,overloadRun);}else overloadRun=0;if(value<=.08f){silent++;silentRun++;maxSilence=Math.max(maxSilence,silentRun);}else silentRun=0;}float suggested=peak<=.001f?1f:Math.min(1f,.9f/peak);return new Result(peak,suggested,overload,silent,maxOverload,maxSilence,points.length);}
}
